3	{% block extra_style %}
4	  .join-wrap{max-width:560px;margin:0 auto;padding:64px 24px 100px;}
5	  .join-wrap h1{font-size:26px;font-weight:900;margin-bottom:8px;text-align:center;}
6	  .join-wrap .desc{text-align:center;color:var(--sub);font-size:14px;margin-bottom:24px;}
7	  .join-card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:32px 28px;box-shadow:0 4px 16px rgba(0,0,0,.06);}
8	  .join-card label{display:block;font-size:14px;font-weight:700;color:var(--ink);margin:18px 0 6px;}
9	  .join-card label:first-of-type{margin-top:0;}
10	  .required{color:var(--red);}
11	  .join-card input[type=text],.join-card input[type=url],.join-card textarea{
12	    width:100%;padding:11px 14px;font-size:15px;border-radius:8px;border:1px solid var(--line);
13	    background:var(--paper);color:var(--ink);font-family:inherit;
14	  }
15	  .join-card textarea{resize:vertical;min-height:120px;line-height:1.6;}
16	  .join-card input[type=file]{width:100%;padding:10px 0;}
17	  .current-photo{margin-top:8px;}
18	  .current-photo img{width:80px;height:80px;object-fit:cover;border-radius:8px;}
19	  .links-hint{font-size:13px;color:var(--sub);margin:24px 0 4px;}
20	  .link-row{display:flex;gap:8px;margin-top:8px;align-items:center;}
21	  .link-row input[type=url]{flex:1;min-width:0;}
22	  .edit-label-btn{
23	    width:auto;flex:0 0 auto;margin-top:0;padding:11px 12px;border:1px solid var(--line);border-radius:8px;
24	    background:transparent;color:var(--sub);font-size:13px;cursor:pointer;font-family:inherit;white-space:nowrap;
25	  }
26	  .edit-label-btn:hover{border-color:var(--red);color:var(--red);}
27	  .label-input{margin-top:6px;}
28	  .hint{font-size:13px;color:var(--sub);margin-top:6px;}
29	  .join-card button.save-btn{
30	    width:100%;margin-top:28px;padding:14px;font-size:16px;font-weight:900;border:none;
31	    border-radius:8px;background:var(--red);color:#fff;cursor:pointer;font-family:inherit;
32	  }
33	  .join-card button.save-btn:hover{background:var(--red-dark);}
