44	{% block body %}
45	<div class="join-wrap">
46	  <h1>修改我的資料</h1>
47	  <p class="desc">這是您的專屬編輯連結，只有您能看到並修改這份資料</p>
48	  <div class="join-card">
49	    {% if error %}<div class="error">{{ error }}</div>{% endif %}
50	    {% if saved %}<div class="saved">已儲存修改</div>{% endif %}
51	    <form method="POST" enctype="multipart/form-data">
52	      {% set f = form if form else member %}
53	      <label>姓名 <span class="required">*</span></label>
54	      <input type="text" name="name" value="{{ f.name if f else '' }}" required>
55	
56	      <label>公司 / 職稱 <span class="required">*</span></label>
57	      <input type="text" name="company_title" value="{{ f.company_title if f else '' }}" required>
58	
59	      <label>產業別／頭銜標籤（選填）</label>
60	      <input type="text" name="role_tag" value="{{ (f.role_tag if f else '') or '' }}">
61	
62	      <label>簡介 <span class="required">*</span></label>
63	      <textarea name="bio" required>{{ f.bio if f else '' }}</textarea>
64	
65	      <label>照片</label>
66	      <div class="current-photo"><img src="{{ url_for('static', filename='uploads/' ~ member.photo_filename) }}" alt="{{ member.name }}"></div>
67	      <div class="hint">不上傳新照片就會保留目前這張</div>
68	      <input type="file" name="photo" accept="image/jpeg,image/png,image/webp">
69	
70	      <div class="links-hint">以下連結都選填。內建按鈕文字就是平台名稱，不用理會就會這樣顯示；如果想改成別的文字，按「修改標籤」再輸入</div>
71	
72	      {% set link_defs = [
73	        ('website_url', 'website_label', '官網', '官網', 'https://...'),
74	        ('fb_url', 'fb_label', 'FB 粉絲專頁', 'FB', 'https://facebook.com/...'),
75	        ('ig_url', 'ig_label', 'IG', 'IG', 'https://instagram.com/...'),
76	        ('threads_url', 'threads_label', 'Threads', 'Threads', 'https://threads.net/...'),
77	        ('youtube_url', 'youtube_label', 'YouTube', 'YouTube', 'https://youtube.com/...'),
78	        ('gjw_url', 'gjw_label', '乾淨世界 GJW', 'GJW', 'https://www.ganjing.world/...'),
79	        ('line_url', 'line_label', 'LINE', 'LINE', 'https://line.me/...'),
80	        ('podcast_url', 'podcast_label', 'Podcast', 'Podcast', 'https://...'),
81	        ('blog_url', 'blog_label', '部落格文章', '部落格', 'https://...'),
82	      ] %}
83	      {% for url_name, label_name, field_title, default_label, placeholder in link_defs %}
84	      {% set label_val = (f[label_name] if f else '') or '' %}
85	      <label>{{ field_title }}</label>
86	      <div class="link-row">
87	        <input type="url" name="{{ url_name }}" value="{{ (f[url_name] if f else '') or '' }}" placeholder="{{ placeholder }}">
88	        <button type="button" class="edit-label-btn" onclick="toggleLabelEdit(this)">修改標籤</button>
