# ---------- 邀約來賓紀錄表(2026-08-30，真誠分會示範) ----------

def list_invite_teams(conn, chapter_id):
    return conn.execute(
        "SELECT * FROM invite_teams WHERE chapter_id = ? ORDER BY sort_order ASC, id ASC", (chapter_id,)
    ).fetchall()


def list_invite_members(conn, chapter_id):
    """依小組排序、組內依sort_order排序；未分組(team_id為NULL)排最後。"""
    return conn.execute(
        """
        SELECT im.*, it.team_name, it.sort_order AS team_sort_order
        FROM invite_members im
        LEFT JOIN invite_teams it ON it.id = im.team_id
        WHERE im.chapter_id = ?
        ORDER BY (it.sort_order IS NULL) ASC, it.sort_order ASC, im.sort_order ASC, im.id ASC
        """,
        (chapter_id,),
    ).fetchall()


def list_invite_weeks(conn, chapter_id):
    return conn.execute(
        "SELECT * FROM invite_weeks WHERE chapter_id = ? ORDER BY week_date ASC", (chapter_id,)
    ).fetchall()


def list_invite_records(conn, chapter_id):
    """完整來賓名單，含週次日期跟邀約人姓名，依週次+id排序。"""
    return conn.execute(
        """
        SELECT ir.*, iw.week_date, iw.note AS week_note, im.name AS member_name
        FROM invite_records ir
        JOIN invite_weeks iw ON iw.id = ir.week_id
        JOIN invite_members im ON im.id = ir.member_id
        WHERE ir.chapter_id = ?
        ORDER BY iw.week_date ASC, ir.id ASC
        """,
        (chapter_id,),
    ).fetchall()


def build_invite_summary(members, weeks, records):
    """算出每位會員在各(可計算)週次的邀約數、目前連續無來賓週數、標籤等級。
    is_meeting=0的週(如內訓)整週跳過，不計入連續無來賓也不顯示在矩陣欄位。"""
    meeting_weeks = [w for w in weeks if w["is_meeting"]]
    counts = defaultdict(int)
    for r in records:
        counts[(r["member_id"], r["week_id"])] += 1

    rows = []
    for m in members:
        week_counts = [counts.get((m["id"], w["id"]), 0) for w in meeting_weeks]
        total = sum(week_counts)
        streak = 0
        for c in reversed(week_counts):
            if c == 0:
                streak += 1
            else:
                break
        if streak >= 8:
            label = "🔴 連續8週以上無來賓・建議寄警告信"
        elif streak >= 4:
            label = "🟡 連續4週以上無來賓"
        elif streak > 0:
            label = f"已連續{streak}週無來賓"
        else:
            label = ""
        rows.append({
            "member": m,
            "week_counts": week_counts,
            "total": total,
            "streak": streak,
            "label": label,
        })
    return {"meeting_weeks": meeting_weeks, "rows": rows}

